import { useSelector } from "@tanstack/react-form"
import { Spinner } from "@/components/ui/spinner"
import { useFieldContext } from "../../hooks/use-app-form"
import type { ReactNode } from "react"

export interface FieldValidatingProps {
    label?: ReactNode
    /**
     * Overrides the field's built-in `meta.isValidating`. Pass this when the
     * field's async validator is driven by `useAsyncFieldValidator` (see hook
     * docs for why the built-in flag isn't reliable across repeated validations).
     */
    isValidating?: boolean
}

export function FieldValidating({ label = "Checking…", isValidating: isValidatingOverride }: Readonly<FieldValidatingProps>) {
    const field = useFieldContext()
    const metaIsValidating = useSelector(field.store, (state) => state.meta.isValidating)
    const isValidating = isValidatingOverride ?? metaIsValidating

    if (!isValidating) return null

    return (
        <div className="flex items-center gap-1.5 text-[0.8rem] text-muted-foreground">
            <Spinner className="size-3" />
            {label}
        </div>
    )
}

import * as React from "react"
import { Card, CardContent, CardHeader } from "@/components/ui/card"
import { useFieldContext } from "../../hooks/use-app-form"
import { cn } from "@/lib/utils"

export interface FormFieldCardSelectOption<V = string> {
    value: V
    label: string
    icon?: React.ReactNode
}

interface RenderProps<O extends FormFieldCardSelectOption<any> = FormFieldCardSelectOption<string>> {
    option: O
    isSelected: boolean
    index: number
    setValue: () => void
}

interface FormCardSelectFieldProps<O extends FormFieldCardSelectOption<any> = FormFieldCardSelectOption<string>> {
    render?: (props: RenderProps<O>) => React.ReactNode
    options: Array<O>
    className?: string
}

export function FormCardSelectField<O extends FormFieldCardSelectOption<any>>({ render, options, className }: Readonly<FormCardSelectFieldProps<O>>) {
    const field = useFieldContext()

    return (
        <div className={cn('flex gap-2 w-full', className)}>
            {options.map((option, index) => {
                const isSelected = option.value === field.state.value
                const setValue = () => {
                    field.setValue(option.value)
                }
                if (render) return render({
                    option,
                    isSelected,
                    index,
                    setValue
                })
                return (
                    <Card key={option.value + index} onClick={() => setValue()} className={
                        cn("basis-0 grow",
                            isSelected && 'bg-primary text-primary-foreground'
                        )
                    }>
                        <CardHeader>
                            {option.icon}
                        </CardHeader>
                        <CardContent>
                            {option.label}
                        </CardContent>
                    </Card>
                )
            })}
        </div>
    )
}

import { Input } from "@/components/ui/input"
import { useFieldContext } from "../../hooks/use-app-form"
import { useEffect, useRef } from "react"

export function FormFieldInput(props: Readonly< React.ComponentProps<"input">>) {
    const field = useFieldContext<string>()
    const inputRef = useRef<HTMLInputElement>(null)

    const errors = field.state.meta.errors

    useEffect(() => {
        if (errors.length > 0 && inputRef.current) {
            inputRef.current.focus()
        }
    }, [errors])
    return (
        <Input
            ref={inputRef}
            aria-invalid={errors.length > 0}
            {...props}
        />
    )
}

